const ASSETS=['assets/photo-wedding.png','assets/photo-session.png','assets/photo-product.png'];
const DEMO_VIDEO='https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4';
const cp=x=>JSON.parse(JSON.stringify(x??{}));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const color=(v,f)=>/^(#[0-9a-f]{3,8}|rgba?\([\d\s.,%]+\)|hsla?\([\d\s.,%]+\))$/i.test(String(v||'').trim())?String(v).trim():f;
const href=(v,f='#')=>{const s=String(v||'').trim();if(!s)return f;if(s.startsWith('#')||s.startsWith('/')||s.startsWith('assets/'))return s;try{const u=new URL(s,location.href);return['http:','https:','mailto:','tel:'].includes(u.protocol)?u.href:f}catch{return f}};
const img=(v,f=ASSETS[0])=>{const u=href(v,'');return u&&/^(https?:|\/|assets\/)/.test(u)?u:f};
const itemId=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
const common=(type,title,subtitle='')=>({id:'w'+itemId(),type,title,subtitle,theme:'dark',background:'#0a0a0a',textColor:'#ffffff',accent:'#ffffff',paddingTop:90,paddingBottom:90,hidden:false,createdAt:Date.now()});

